input.sparql:
PREFIX brick: <http://brickschema.org/schema/1.1/brick#>
SELECT ?s ?class ?lbl WHERE {
  ?s a brick:AirTemperatureSensor ; brick:hasLocation ?zone .
  ?zone a brick:Zone .
  ?s a ?class .
  OPTIONAL { ?s rdfs:label ?lbl }
}

SELECT ?s ?class ?lbl ?zone WHERE {
  ?s a ?class .
  FILTER(strstarts(str(?class), "https://brickschema.org/schema/Brick#AirTemperature") || strstarts(str(?class), "http://brickschema.org/schema/1.1/brick#AirTemperature"))
  OPTIONAL { ?s rdfs:label ?lbl }
  OPTIONAL { ?s <https://brickschema.org/schema/Brick/hasLocation> ?zone }
} LIMIT 50
